assert ghost_head(parent, {"v1": "a", "v2": "b2", "v3": "b2", "v4": "b2", "v5": "b2"}, heavy, "r") == "a2", \
    "stake, not the number of validators, decides; below a vote, an unvoted tie goes to the larger id"
assert ghost_head({}, {}, {}, "r") == "r"
long_parent = {"x0": "r"}
